function wireCampaignSlider(root = mount) {
  const slider = root.querySelector('.campaign-slider'); if (!slider || slider.dataset.ready) return;
  slider.dataset.ready = 'true';
  const track = slider.querySelector('.campaign-track');
  const slides = [...slider.querySelectorAll('.campaign-slide')];
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  let index = 0; let timer;
  const show = next => {
    index = (next + slides.length) % slides.length;
    track.style.transform = `translate3d(-${index * 100}%,0,0)`;
    slides.forEach((slide, i) => { const active = i === index; slide.setAttribute('aria-hidden', String(!active)); slide.tabIndex = active ? 0 : -1; });
  };
  const stop = () => window.clearInterval(timer);
  const start = () => { stop(); if (!reduceMotion) timer = window.setInterval(() => show(index + 1), 4000); };
  slider.addEventListener('mouseenter', stop); slider.addEventListener('mouseleave', start);
  slider.addEventListener('focusin', stop); slider.addEventListener('focusout', start);
  show(0); start();
}

async function appendSharedTravelSections() {
  const first = location.pathname.split('/').filter(Boolean)[0] || '';
  if (['login', 'signup', 'profile'].includes(first)) return;
  if (!mount.querySelector('.campaign-slider')) mount.insertAdjacentHTML('beforeend', offersSliderSection());
  if (!mount.querySelector('.reasons-section')) mount.insertAdjacentHTML('beforeend', reasonsSection());
  if (!mount.querySelector('.review-track')) mount.insertAdjacentHTML('beforeend', reviewsSection());
  if (!mount.querySelector('.activities')) mount.insertAdjacentHTML('beforeend', activitiesSection());
  if (!mount.querySelector('.journal-grid')) {
    const blogs = await api('/blogs').catch(() => []);
    if (blogs.length) mount.insertAdjacentHTML('beforeend', journalSection(blogs.slice(0, 5)));
  }
  applyTailwindStyles(mount); activateIcons(); wireCampaignSlider(mount); wireRails();
}

function wireRails() {
  const wireRail = (trackSelector, prevSelector, nextSelector, itemSelector, fallback) => {
    const track = document.querySelector(trackSelector); if (!track) return;
    const prev = document.querySelector(prevSelector); const next = document.querySelector(nextSelector);
    const step = () => (track.querySelector(itemSelector)?.getBoundingClientRect().width || fallback) + 20;
    prev?.addEventListener('click', () => track.scrollBy({ left: -step(), behavior: 'smooth' }));
    next?.addEventListener('click', () => track.scrollBy({ left: step(), behavior: 'smooth' }));
    const update = () => { if (prev) prev.disabled = track.scrollLeft < 5; if (next) next.disabled = track.scrollLeft + track.clientWidth >= track.scrollWidth - 5; };
    track.addEventListener('scroll', update, { passive: true }); window.addEventListener('resize', update, { passive: true }); update();
  };
  wireRail('#review-track', '#review-prev', '#review-next', '.review-card', 340);
  wireRail('#activities-track', '#activities-prev', '#activities-next', '.activity-card', 280);
  wireReviewAutoplay('#review-track');
  wireJournalScale();
  wireElasticDrag('.journal-grid');
  wireElasticDrag('.review-track');
  wireElasticDrag('#activities-track');
  wireElasticDrag('.category-tabs');
  wireElasticDrag('.hotel-destination-tabs');
  wireElasticDrag('.hotel-quick-filters');
}

// Left/right elastic drag: click-and-drag (or touch-drag) the track past its
// start or end and it stretches with resistance, then springs back — like a
// native rubber-band scroll, but also works with a mouse (native overflow
// scroll has no drag-to-scroll at all).
function wireElasticDrag(trackSelector) {
  document.querySelectorAll(trackSelector).forEach(track => {
    if (track.dataset.elasticReady) return;
    track.dataset.elasticReady = 'true';
    let isDown = false, startX = 0, startScroll = 0, overshoot = 0, dragged = false, raf = null;

    const maxScroll = () => track.scrollWidth - track.clientWidth;
    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const applyOvershoot = amount => {
      overshoot = amount;
      track.style.transform = amount ? `translate3d(${-amount}px, 0, 0)` : '';
    };
    const settle = () => {
      if (prefersReducedMotion) { applyOvershoot(0); return; }
      const start = overshoot; const startTime = performance.now(); const duration = 280;
      const step = now => {
        const t = Math.min(1, (now - startTime) / duration);
        applyOvershoot(start * (1 - (1 - Math.pow(1 - t, 3))));
        if (t < 1) raf = requestAnimationFrame(step); else { track.style.transform = ''; overshoot = 0; }
      };
      raf = requestAnimationFrame(step);
    };
    const eventX = e => e.clientX ?? e.touches?.[0]?.clientX ?? 0;
    const pointerDown = e => {
      if (e.button !== undefined && e.button !== 0) return;
      isDown = true; dragged = false;
      track.style.cursor = 'grabbing';
      startX = eventX(e);
      startScroll = track.scrollLeft;
      try { track.setPointerCapture?.(e.pointerId); } catch {}
      if (raf) cancelAnimationFrame(raf);
    };
    const pointerMove = e => {
      if (!isDown) return;
      const x = eventX(e);
      const delta = startX - x;
      if (Math.abs(delta) > 6) dragged = true;
      const next = startScroll + delta;
      const max = maxScroll();
      if (next < 0) { track.scrollLeft = 0; applyOvershoot(Math.max(-56, Math.min(56, next * 0.52))); }
      else if (next > max) { track.scrollLeft = max; applyOvershoot(Math.max(-56, Math.min(56, (next - max) * 0.52))); }
      else { track.scrollLeft = next; if (overshoot) applyOvershoot(0); }
      if (e.cancelable && dragged) e.preventDefault();
    };
    const pointerUp = e => {
      if (!isDown) return;
      isDown = false;
      track.style.cursor = 'grab';
      try { track.releasePointerCapture?.(e?.pointerId); } catch {}
      if (overshoot) settle();
    };
    track.style.cursor = 'grab';
    track.style.touchAction = 'pan-y';
    track.addEventListener('pointerdown', pointerDown);
    track.addEventListener('pointermove', pointerMove);
    track.addEventListener('pointerup', pointerUp);
    track.addEventListener('pointercancel', pointerUp);
    track.addEventListener('click', e => { if (dragged) { e.preventDefault(); e.stopPropagation(); } }, true);
    // Images/links inside the track are draggable by default in the browser;
    // that native drag hijacks the mouseup event so our spring-back never runs.
    track.addEventListener('dragstart', e => e.preventDefault());
  });
}

// Embla-style "peek" carousel: the card nearest the track's centre scales up
// to full size, the rest sit at 0.9 — driven by scroll position, not :hover,
// so it also works on touch.
function wireJournalScale() {
  document.querySelectorAll('.journal-grid').forEach(track => {
    if (track.dataset.scaleReady) return;
    track.dataset.scaleReady = 'true';
    const cards = [...track.querySelectorAll('.journal-card')];
    if (!cards.length) return;
    const update = () => {
      const trackRect = track.getBoundingClientRect();
      const center = trackRect.left + trackRect.width / 2;
      let closest = null, closestDist = Infinity;
      cards.forEach(card => {
        const r = card.getBoundingClientRect();
        const dist = Math.abs((r.left + r.width / 2) - center);
        if (dist < closestDist) { closestDist = dist; closest = card; }
      });
      cards.forEach(card => { card.style.transform = card === closest ? 'scale(1)' : 'scale(0.9)'; });
    };
    track.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update, { passive: true });
    update();
  });
}

// Below the desktop breakpoint, reviews show one card per screen — auto-advance
// through them instead of requiring a manual swipe/arrow tap.
function wireReviewAutoplay(trackSelector) {
  const track = document.querySelector(trackSelector);
  if (!track || track.dataset.autoplayReady || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  track.dataset.autoplayReady = 'true';
  const isSingleCardLayout = () => window.innerWidth <= 1099;
  let timer;
  const stop = () => window.clearInterval(timer);
  const advance = () => {
    if (!isSingleCardLayout()) return;
    const atEnd = track.scrollLeft + track.clientWidth >= track.scrollWidth - 5;
    track.scrollTo({ left: atEnd ? 0 : track.scrollLeft + track.clientWidth, behavior: 'smooth' });
  };
  const start = () => { stop(); if (isSingleCardLayout()) timer = window.setInterval(advance, 4000); };
  track.addEventListener('mouseenter', stop);
  track.addEventListener('mouseleave', start);
  track.addEventListener('touchstart', stop, { passive: true });
  track.addEventListener('touchend', start, { passive: true });
  window.addEventListener('resize', start, { passive: true });
  start();
}

