function amenityIcon(amenity) {
  const a = String(amenity || '').toLowerCase();
  if (a.includes('wifi')) return 'wifi';
  if (a.includes('breakfast')) return 'coffee';
  if (a.includes('restaurant') || a.includes('dining') || a.includes('caf') || a.includes('kitchen')) return 'utensils-crossed';
  if (a.includes('gym')) return 'dumbbell';
  if (a.includes('pool')) return 'waves';
  if (a.includes('spa') || a.includes('oxygen') || a.includes('wellness')) return 'wind';
  if (a.includes('parking')) return 'car-front';
  if (a.includes('airport') || a.includes('transfer')) return 'plane';
  if (a.includes('heating') || a.includes('heater')) return 'snowflake';
  if (a.includes('hot water') || a.includes('toiletries') || a.includes('bath')) return 'droplets';
  if (a.includes('bonfire') || a.includes('fireplace')) return 'flame';
  if (a.includes('balcony') || a.includes('sit-out')) return 'door-open';
  if (a.includes('mini bar') || a.includes('minibar') || a.includes('fridge')) return 'refrigerator';
  if (a.includes('yoga')) return 'sparkles';
  if (a.includes('shuttle')) return 'car-front';
  if (a.includes('bicycle') || a.includes('bike hire')) return 'bike';
  if (a.includes('kayak') || a.includes('boat') || a.includes('water')) return 'ship';
  if (a.includes('family') || a.includes('kids')) return 'baby';
  if (a.includes('garden')) return 'trees';
  if (a.includes('mountain') || a.includes('view') || a.includes('trek') || a.includes('walk')) return 'mountain';
  return 'sparkles';
}
function starRow(hotel, cls = 'hotel-card-stars') {
  const filled = Math.min(5, Math.max(1, Math.round(hotel.star || 4)));
  return `<span class="${cls}" role="img" aria-label="${hotel.star} star hotel">${Array.from({ length: filled }, () => icon('star')).join('')}${Array.from({ length: 5 - filled }, () => `<span class="hotel-star-empty">${icon('star')}</span>`).join('')}</span>`;
}
function hotelRoomCard(hotel, room) {
  return `<article class="hotel-room-card"><div class="hotel-room-media"><img src="${esc(hotel.image)}" alt="${esc(room.name)}" loading="lazy" /><span>${icon('mountain')} ${esc(room.view || 'Comfortable stay')}</span></div><div class="hotel-room-body"><h3>${esc(room.name)}</h3><p>Comfort designed around restful nights and an easy stay.</p><div class="hotel-room-meta"><span>${icon('bed')} ${esc(room.bed)}</span><span>${icon('users')} ${esc(room.occupancy)}</span><span>${icon('maximize')} ${esc(room.size)}</span></div><div class="hotel-room-perks">${(room.perks || []).map(p => `<span>${icon('check')} ${esc(p)}</span>`).join('')}</div></div><div class="hotel-room-price"><small>Price for one night</small><strong>${money(room.price)}</strong><del>${money(room.oldPrice)}</del><span class="hotel-tax-note">+ taxes · free cancellation</span><button class="btn" type="button" data-room="${esc(room.name)}" data-price="${room.price}">${icon('calendar-clock')} Choose room</button></div></article>`;
}
function ratingDistribution(rating) {
  const five = Math.min(92, Math.round(30 + (rating - 3.5) * 55));
  const four = Math.min(40, Math.max(4, Math.round((5 - rating) * 18)));
  const three = Math.max(1, Math.round((5 - rating) * 4));
  const two = Math.max(0, Math.round((5 - rating) * 2));
  const one = Math.max(0, 100 - five - four - three - two);
  return [['5', five], ['4', four], ['3', three], ['2', two], ['1', one]];
}
const isoDate = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

