function wireHotelExperience() {
  const links = [...document.querySelectorAll('.hotel-detail-nav a[href^="#"]')];
  const sections = links.map(link => document.querySelector(link.getAttribute('href'))).filter(Boolean);
  if ('IntersectionObserver' in window) {
    const navObserver = new IntersectionObserver(entries => { const active = entries.filter(x => x.isIntersecting).sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0]; if (active) links.forEach(link => link.classList.toggle('active', link.getAttribute('href') === `#${active.target.id}`)); }, { rootMargin: '-25% 0px -65% 0px', threshold: [0, .1, .4] });
    sections.forEach(section => navObserver.observe(section));
  }
  const revealItems = [...document.querySelectorAll('.hotel-gallery-wrap,.hotel-fact,.hotel-amenity-item,.hotel-room-card,.hotel-nearby-list li,.hotel-section .side-card')];
  if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches && 'IntersectionObserver' in window) {
    const revealObserver = new IntersectionObserver(entries => entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('is-visible'); revealObserver.unobserve(entry.target); } }), { rootMargin: '0px 0px -8% 0px', threshold: .1 });
    revealItems.forEach((item, index) => { item.classList.add('hotel-reveal'); item.style.setProperty('--hotel-delay', `${Math.min(index % 4, 3) * 65}ms`); revealObserver.observe(item); });
  } else revealItems.forEach(item => item.classList.add('is-visible'));
}

