function wireTripExperience(trip){
  const steps=[['itinerary','Itinerary'],['inclusions','Inclusions'],['costing','Costing'],['notes','Notes']];
  const links=[...document.querySelectorAll('.trip-audit-tabs a')];
  const setActive=id=>{links.forEach(link=>{const active=link.getAttribute('href')===`#${id}`;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','step');else link.removeAttribute('aria-current')})};
  const observer=new IntersectionObserver(entries=>{const visible=entries.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(visible)setActive(visible.target.id)},{rootMargin:'-35% 0px -55% 0px',threshold:[0,.1,.3,.6]});
  steps.forEach(([id])=>{const section=document.getElementById(id);if(section)observer.observe(section)});setActive('itinerary');
  const countEl=document.querySelector('[data-count]');let count=1;
  document.querySelectorAll('[data-count-minus],[data-count-plus]').forEach(btn=>btn.addEventListener('click',()=>{count=btn.dataset.countMinus!==undefined?Math.max(1,count-1):Math.min(30,count+1);if(countEl)countEl.textContent=count;}));
  document.querySelectorAll('[data-book-now]').forEach(btn=>btn.addEventListener('click',()=>openDepartureForm(trip,trip.dates?.[0]||'your preferred dates',btn,count)));
  document.querySelectorAll('[data-departure]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.trip-date-row').forEach(row=>row.classList.toggle('selected',row===button));openDepartureForm(trip,button.dataset.departure,button,count);}));
  const monthSelect=document.querySelector('[data-month-select]'),dateRows=[...document.querySelectorAll('.trip-date-row')];
  const applyMonthFilter=()=>{const month=monthSelect?.value;dateRows.forEach(row=>row.classList.toggle('hidden',Boolean(month)&&row.dataset.month!==month));};
  monthSelect?.addEventListener('change',applyMonthFilter);
  applyMonthFilter();
  const more=document.querySelector('[data-read-more]'),aboutCopy=document.querySelector('.trip-about-copy');
  more?.addEventListener('click',()=>openAboutPopup(trip.title,aboutCopy?.innerHTML||''));
  document.querySelectorAll('[data-download-itinerary]').forEach(btn=>btn.addEventListener('click',()=>downloadItinerary(trip)));
  document.querySelectorAll('.breakdown-item').forEach(item=>{
    const toggle=item.querySelector('.breakdown-toggle');
    toggle?.addEventListener('click',()=>{
      const open=item.classList.toggle('open');
      toggle.setAttribute('aria-expanded',String(open));
    });
  });
}

function openAboutPopup(title,bodyHtml){
  document.querySelector('.about-modal')?.remove();
  document.body.insertAdjacentHTML('beforeend',`<div class="about-modal open"><button class="about-backdrop" type="button" aria-label="Close"></button><section class="about-dialog" role="dialog" aria-modal="true" aria-labelledby="about-title"><button class="about-close" type="button" aria-label="Close">${icon('x')}</button><span class="about-kicker">${icon('circle-check-big')} About this trip</span><h2 id="about-title">${esc(title)}</h2>${bodyHtml}</section></div>`);
  const modal=document.querySelector('.about-modal');applyTailwindStyles();activateIcons();
  const close=()=>modal.remove();
  modal.querySelectorAll('.about-backdrop,.about-close').forEach(x=>x.addEventListener('click',close));
  const escape=e=>{if(e.key==='Escape'){document.removeEventListener('keydown',escape);close()}};document.addEventListener('keydown',escape);
}

function downloadItinerary(trip){
  const lines=[`${trip.title} — Itinerary`,``,`${trip.duration} · ${trip.groupSize} · ${trip.pickup}`,``,...(trip.itinerary||[]).map(day=>`Day ${day.day}: ${day.title}\n  ${(day.details||[]).join('\n  ')}`),``,`Included: ${(trip.inclusions||[]).join(', ')}`,``,`Not included: ${(trip.exclusions||[]).join(', ')}`];
  const blob=new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'});
  const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${trip.slug||trip.title.replace(/\s+/g,'-').toLowerCase()}-itinerary.txt`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}

function departureInputValue(label){const parsed=new Date(`${label} ${new Date().getFullYear()}`);if(Number.isNaN(parsed.getTime()))return '';if(parsed<new Date())parsed.setFullYear(parsed.getFullYear()+1);return `${parsed.getFullYear()}-${String(parsed.getMonth()+1).padStart(2,'0')}-${String(parsed.getDate()).padStart(2,'0')}`}
function openDepartureForm(trip,dateLabel,trigger,count=1){
  document.querySelector('.departure-modal')?.remove();
  document.body.insertAdjacentHTML('beforeend',`<div class="departure-modal open"><button class="departure-backdrop" type="button" aria-label="Close departure form"></button><section class="departure-dialog" role="dialog" aria-modal="true" aria-labelledby="departure-title"><button class="departure-close" type="button" aria-label="Close">${icon('x')}</button><span class="departure-kicker">${icon('calendar-days')} Selected departure</span><h2 id="departure-title">Travel on ${esc(dateLabel)}</h2><p>${esc(trip.title)} · Our expert will confirm availability before you pay.</p><form class="departure-form"><label>Full name<input name="name" required autocomplete="name" placeholder="Your name"></label><label>Phone number<input name="phone" type="tel" required autocomplete="tel" placeholder="+91 98765 43210"></label><label>Travel date<input name="travelDate" type="date" value="${departureInputValue(dateLabel)}" required></label><input type="hidden" name="destination" value="${esc(trip.title)}"><input type="hidden" name="type" value="selected-departure"><input type="hidden" name="travellers" value="${count}"><button class="btn btn-primary" type="submit">${icon('send')} Request this date</button><p class="form-status" role="status"></p></form><small class="departure-safe">${icon('shield-check')} No payment · No spam · Free callback</small></section></div>`);
  const modal=document.querySelector('.departure-modal');applyTailwindStyles();activateIcons();const form=modal.querySelector('form'),close=()=>{modal.remove();trigger?.focus()};modal.querySelectorAll('.departure-backdrop,.departure-close').forEach(x=>x.addEventListener('click',close));
  const escape=e=>{if(e.key==='Escape'){document.removeEventListener('keydown',escape);close()}};document.addEventListener('keydown',escape);modal.querySelector('input')?.focus();
  form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button[type=submit]'),status=form.querySelector('.form-status');button.disabled=true;status.textContent='Saving your selected departure…';try{const body={...Object.fromEntries(new FormData(form)),travellers:Number(count)||1};const response=await fetch('/api/enquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error();status.className='form-status success';status.textContent='Date request received. Our expert will call you shortly.';setTimeout(close,1800)}catch{status.className='form-status error';status.textContent='Could not save right now. Please try again.'}finally{button.disabled=false}})
}

async function renderTripLegacy(slug) {
  const trip=await api(`/trips/${slug}`); setMeta(trip.title,trip.summary);
  mount.innerHTML=hero({title:trip.title,description:trip.summary,image:trip.image,eyebrow:`${trip.duration} • ${trip.badge}`,crumbs:[{href:'/trips',label:'Trips'}]})+`<nav class="detail-tabs"><div class="container"><a href="#overview">Overview</a><a href="#itinerary">Itinerary</a><a href="#inclusions">Inclusions</a><a href="#dates">Dates</a><a href="#notes">Notes</a></div></nav><section class="content-section" id="overview"><div class="container content-grid"><article class="prose"><h2>About the trip</h2><p>${esc(trip.summary)}</p><h2>Trip details</h2><ul><li><strong>Duration:</strong> ${esc(trip.duration)}</li><li><strong>Group size:</strong> ${esc(trip.groupSize)}</li><li><strong>Pickup:</strong> ${esc(trip.pickup)}</li></ul><h2 id="itinerary">Itinerary breakdown</h2><div class="timeline">${trip.itinerary.map(day=>`<div class="timeline-item"><span class="day-pill">D${day.day}</span><div><h3>${esc(day.title)}</h3>${day.details.map(x=>`<p>${esc(x)}</p>`).join('')}</div></div>`).join('')}</div><h2 id="inclusions">What’s in the package?</h2><div class="two-col-list"><div class="list-panel"><h3>Included</h3><ul>${trip.inclusions.map(x=>`<li>${icon('check')} ${esc(x)}</li>`).join('')}</ul></div><div class="list-panel"><h3>Not included</h3><ul>${trip.exclusions.map(x=>`<li>${icon('x')} ${esc(x)}</li>`).join('')}</ul></div></div><h2 id="dates">Upcoming dates</h2><p>${trip.dates.map(x=>`<span class="filter-pill">${icon('calendar-days')} ${esc(x)}</span>`).join(' ')}</p><h2 id="notes">Important notes</h2><ul>${trip.notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></article><aside class="side-card"><span>Starting from</span><span class="trip-price-big">${money(trip.price)}</span><p><del>${money(trip.oldPrice)}</del> · ${esc(trip.discount)}</p><ul><li>${trip.duration}</li><li>${trip.groupSize}</li><li>20% to reserve your seat</li></ul><a class="btn btn-primary btn-block" href="/custom-trip?destination=${esc(trip.destinationSlug)}&trip=${esc(trip.slug)}">Send enquiry</a></aside></div></section>`;
}

function enquiryForm(type='custom') { return `<form class="form-card" id="enquiry-form"><div class="form-grid"><div class="field"><label for="name">Full name</label><input id="name" name="name" required autocomplete="name" /></div><div class="field"><label for="phone">Phone</label><input id="phone" name="phone" type="tel" required autocomplete="tel" /></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required autocomplete="email" /></div><div class="field"><label for="destination">Destination</label><input id="destination" name="destination" required /></div><div class="field"><label for="travelDate">Travel date</label><input id="travelDate" name="travelDate" type="date" /></div><div class="field"><label for="travellers">Travellers</label><input id="travellers" name="travellers" type="number" min="1" value="1" /></div><div class="field"><label for="budget">Budget per person</label><select id="budget" name="budget"><option>Under ₹20,000</option><option>₹20,000–₹50,000</option><option>₹50,000–₹1,00,000</option><option>Above ₹1,00,000</option></select></div><div class="field full"><label for="message">Trip preferences</label><textarea id="message" name="message" placeholder="Tell us about stays, activities, departure city or anything important."></textarea></div><div class="field full"><button class="btn btn-primary" type="submit">${icon('send')} Send enquiry</button></div></div><p class="form-status" role="status"></p><input type="hidden" name="type" value="${type}" /></form>`; }
function wireForm(){const form=document.querySelector('#enquiry-form');if(!form)return;const params=new URLSearchParams(location.search);if(params.get('destination'))form.destination.value=params.get('destination');form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button');const status=form.querySelector('.form-status');button.disabled=true;status.textContent='Sending…';try{const body=Object.fromEntries(new FormData(form));body.travellers=Number(body.travellers);const response=await fetch('/api/enquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error();status.className='form-status success';status.textContent='Thanks! Your enquiry is saved. Our travel expert will contact you shortly.';form.reset();}catch{status.className='form-status error';status.textContent='Could not save your enquiry. Please try again.';}finally{button.disabled=false;}})}

async function renderCustom(){setMeta('Plan a Custom Trip','Tell us your preferences and receive a personalised TravelEnfield itinerary.');mount.innerHTML=hero({title:'A trip that feels entirely yours.',description:'Tell us how you like to travel. A real trip expert will shape the route, stays and experiences around you—then explain every detail clearly.',eyebrow:'Personal planning, human support',image:'https://res.cloudinary.com/dq3typk9u/image/upload/v1786542551/travelenfield/custom-trip-consultation.jpg'})+`<section class="custom-proof"><div class="container"><div>${icon('shield-check')}<span><strong>Transparent quote</strong><small>Clear inclusions before you confirm</small></span></div><div>${icon('users')}<span><strong>Real travel expert</strong><small>One person guides your planning</small></span></div><div>${icon('circle-check-big')}<span><strong>Verified partners</strong><small>Handpicked stays and experiences</small></span></div><div>${icon('phone')}<span><strong>Support throughout</strong><small>Help before and during the trip</small></span></div></div></section><section class="custom-planner"><div class="container custom-planner-grid"><aside class="custom-planner-copy"><span class="page-eyebrow">Start with the essentials</span><h2>You dream it.<br>We make it workable.</h2><p>There is no pressure to know the perfect itinerary. Share the basics and our specialist will help you make the right trade-offs.</p><div class="planner-steps"><div><b>01</b><span><strong>Tell us your preferences</strong><small>Dates, people, pace and approximate budget.</small></span></div><div><b>02</b><span><strong>Speak with one expert</strong><small>We understand priorities and propose the right route.</small></span></div><div><b>03</b><span><strong>Review a clear plan</strong><small>Itinerary, stays and inclusions—nothing hidden.</small></span></div></div><div class="planner-promise">${icon('shield-check')}<p><strong>Your details stay private.</strong><br>We only use them to plan and discuss this enquiry.</p></div></aside><div class="custom-form-wrap"><div class="custom-form-head"><span>Usually takes 2 minutes</span><h2>Tell us about your trip</h2><p>No payment required. Our team normally responds within one working day.</p></div>${enquiryForm('custom-trip')}</div></div></section><section class="custom-how"><div class="container"><div class="section-header"><div><span class="page-eyebrow">Why customise?</span><h2 class="section-title">More freedom. Less guesswork.</h2></div></div><div class="custom-benefits"><article>${icon('map-pin')}<h3>Routes built for your pace</h3><p>Slow mornings, packed adventure days, or a balanced mix—the schedule follows you.</p></article><article>${icon('backpack')}<h3>Stays that fit the occasion</h3><p>Friends, families, couples and teams need different spaces. We plan accordingly.</p></article><article>${icon('indian-rupee')}<h3>Budget used where it matters</h3><p>We help prioritise comfort and experiences instead of adding unnecessary extras.</p></article></div></div></section>`;wireForm();}
async function renderBlogs(){const blogs=await api('/blogs');setMeta('Travel Blog','Original destination guides and practical travel advice.');mount.innerHTML=hero({title:'TravelEnfield Journal',description:'Useful guides, real planning advice and destination inspiration.',eyebrow:'Travel smarter',image:'https://res.cloudinary.com/dq3typk9u/image/upload/v1786542569/travelenfield/social-banner.jpg'})+`<section class="page-shell"><div class="container">${filterBar(false)}<div class="cards-grid">${blogs.map(b=>`<article class="listing-card" data-search="${esc((b.title+' '+b.category).toLowerCase())}"><a class="listing-card-media" href="/blog/${b.slug}"><img src="${b.image}" alt="${esc(b.title)}" loading="lazy"></a><div class="listing-card-body"><div class="card-meta">${esc(b.category)} · ${esc(b.readTime)}</div><h2><a href="/blog/${b.slug}">${esc(b.title)}</a></h2><p>${esc(b.excerpt)}</p><a class="card-link" href="/blog/${b.slug}">Read guide ${icon('chevron-right')}</a></div></article>`).join('')}</div></div></section>`;wireFilters();}
async function renderBlog(slug){const b=await api(`/blogs/${slug}`);setMeta(b.title,b.excerpt);mount.innerHTML=hero({title:b.title,description:b.excerpt,image:b.image,eyebrow:b.category,crumbs:[{href:'/blog',label:'Blog'}]})+`<section class="content-section"><article class="container article-layout"><div class="article-meta"><span>${esc(b.author)}</span><span>${esc(b.readTime)}</span><span>${new Date(b.publishedAt).toLocaleDateString('en-IN',{dateStyle:'medium'})}</span></div><div class="prose">${b.sections.map(s=>`<h2>${esc(s.heading)}</h2><p>${esc(s.body)}</p>`).join('')}<h2>Ready to experience it?</h2><p><a class="btn btn-primary" href="/custom-trip">Plan a custom trip</a></p></div></article></section>`;}
async function renderPage(slug){const p=await api(`/pages/${slug}`);setMeta(p.title,p.intro);const contact=slug==='contact-us'?`<section class="page-shell"><div class="container">${enquiryForm('contact')}</div></section>`:'';mount.innerHTML=hero({title:p.title,description:p.intro,eyebrow:p.eyebrow,image:slug==='reviews'?'https://res.cloudinary.com/dq3typk9u/image/upload/v1786542569/travelenfield/social-banner.jpg':'https://res.cloudinary.com/dq3typk9u/image/upload/v1786542561/travelenfield/hero.jpg'})+`<section class="content-section"><div class="container article-layout prose">${p.sections.map(s=>`<h2>${esc(s.heading)}</h2><p>${esc(s.body)}</p>`).join('')}</div></section>${contact}`;wireForm();}
function authForm(){return `<form class="form-card" id="auth-form"><div class="form-grid"><div class="field full signup-only"><label for="auth-name">Name</label><input id="auth-name" name="name" autocomplete="name" /></div><div class="field full"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" required autocomplete="email" /></div><div class="field full"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" minlength="6" required autocomplete="current-password" /></div><div class="field full"><button class="btn btn-primary" type="submit">Continue</button></div></div><p class="form-status" role="status"></p></form>`}
function renderAuth(mode){setMeta(mode==='signup'?'Create Account':'Login','Access your saved trips and enquiries.');mount.innerHTML=hero({title:mode==='signup'?'Create your account':'Welcome back',description:'Save favourites and keep your TravelEnfield journey details together.',eyebrow:'Traveller account'})+`<section class="page-shell"><div class="container">${authForm()}<p class="center">${mode==='signup'?'Already registered? <a href="/login">Login</a>':'New here? <a href="/signup">Create an account</a>'}</p></div></section>`;if(mode==='login')document.querySelector('.signup-only').remove();const form=document.querySelector('#auth-form');form.addEventListener('submit',async e=>{e.preventDefault();const status=form.querySelector('.form-status');try{const response=await fetch(`/api/auth/${mode}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const result=await response.json();if(!response.ok)throw new Error(result.error);localStorage.setItem('travelenfield-user',JSON.stringify(result.user));status.className='form-status success';status.textContent=`Welcome, ${result.user.name}!`; }catch(error){status.className='form-status error';status.textContent=error.message;}})}

async function renderProfile(){
  let user=null;
  try{user=JSON.parse(localStorage.getItem('travelenfield-user')||'null')}catch{}
  if(!user){
    setMeta('My Profile','Login to view your TravelEnfield profile and trips.');
    mount.innerHTML=`<section class="page-shell"><div class="container empty-state"><h1>You're not logged in</h1><p>Login to see your saved details and trip enquiries.</p><button class="btn btn-primary" type="button" id="profile-login-trigger">${icon('log-in')} Login</button></div></section>`;
    document.querySelector('#profile-login-trigger')?.addEventListener('click',()=>setLoginPopup(true));
    document.addEventListener('travelenfield:login',()=>renderProfile(),{once:true});
    return;
  }
  let enquiries=[];
  try{const data=await api(`/profile/${user.id}`);enquiries=data.enquiries||[];if(data.user)user=data.user;}
  catch(error){ if(String(error?.message||'').includes('Not authenticated')){localStorage.removeItem('travelenfield-user');return renderProfile();} }
  setMeta(`${user.name || 'My'} Profile`,'Your TravelEnfield account and trip enquiries.');
  mount.innerHTML=`<section class="profile-hero"><div class="container profile-hero-row"><div class="profile-avatar">${esc((user.name||'U').charAt(0).toUpperCase())}</div><div class="profile-hero-copy"><h1>${esc(user.name||'Traveller')}</h1><p>${esc(user.email||'')}${user.phone?' · '+esc(user.phone):''}</p></div><button class="btn btn-outline-purple" type="button" id="logout-btn">${icon('log-out')} Log out</button></div></section>
  <section class="profile-trips"><div class="container"><h2 class="section-title">Your trip enquiries</h2>${enquiries.length?`<div class="cards-grid profile-trip-grid">${enquiries.map(e=>`<article class="listing-card profile-trip-card"><div class="listing-card-body"><div class="card-meta"><span>${icon('calendar-days')} ${esc(e.travelDate||'Flexible dates')}</span><span class="profile-trip-status">${esc(e.status||'new')}</span></div><h2>${esc(e.destination||e.type||'Trip enquiry')}</h2><p>${esc(e.message||'No additional notes.')}</p><div class="price-row"><span>${icon('users')} ${e.travellers||1} traveller${(e.travellers||1)>1?'s':''}</span></div></div></article>`).join('')}</div>`:`<div class="empty-state"><h3>No enquiries yet</h3><p>Once you send a trip enquiry, it will show up here.</p><a class="btn btn-primary" href="/trips">Explore trips</a></div>`}</div></section>`;
  document.querySelector('#logout-btn')?.addEventListener('click',async()=>{try{await fetch('/api/auth/logout',{method:'POST'})}catch{}localStorage.removeItem('travelenfield-user');window.location.href='/';});
}

function renderRouteLoader(){mount.innerHTML=`<div class="page-loader"><span aria-hidden="true"></span><p>Preparing your next adventure…</p></div>`;}

async function router(){try{renderRouteLoader();const parts=location.pathname.split('/').filter(Boolean);const first=parts[0]||'';if(['trips','upcoming-trips','domestic-trips','international-trips','weekend-trips','deals','backpacking-trips','trekking-trips','bike-trips'].includes(first)&&parts.length===1)await renderListing(first);else if(first==='trips'&&parts[1])await renderTrip(parts[1]);else if(first==='destinations'&&parts[1])await renderDestination(parts[1]);else if(first==='hotels'&&parts.length===1)await renderHotels();else if(first==='hotels'&&parts[1])await renderHotel(parts[1]);else if(first==='custom-trip')await renderCustom();else if(first==='blog'&&!parts[1])await renderBlogs();else if(first==='blog'&&parts[1])await renderBlog(parts[1]);else if(['about-us','contact-us','reviews','faq','privacy-policy','terms-and-conditions','cancellation-policy'].includes(first))await renderPage(first);else if(first==='profile')await renderProfile();else if(['login','signup'].includes(first))renderAuth(first);else throw new Error('Page not found');await appendSharedTravelSections();applyTailwindStyles(mount);activateIcons();}catch(error){setMeta('Page not found','The requested page could not be loaded.');mount.innerHTML=`<section class="page-shell"><div class="container empty-state"><h1>${esc(error.message)}</h1><p>Return to the homepage or explore available trips.</p><a class="btn btn-primary" href="/">Go home</a></div></section>`;applyTailwindStyles(mount);}finally{hideRouteOverlay();}}

router();
